export function isExpired(expiresAt: number, nowMs: number) {
  const now = Math.floor(nowMs / 1000);
  return expiresAt <= now;
}

export function isExpired(expiresAt: number, clock: { now(): number }) {
  const now = clock.now(); // milliseconds
  return expiresAt <= now;
}
